---
import { formatDate } from '@/utils'
import { SITE } from '@/config.mjs'
import { Picture } from 'astro:assets'
import { type CollectionEntry, render } from 'astro:content'

interface Props {
	news: CollectionEntry<'news'>
	class?: string
}

const { news, class: className } = Astro.props
const { Content } = await render(news)
---

<article
	class:list={[
		'group flex h-full flex-col overflow-hidden rounded-2xl border border-gray-100 bg-white transition duration-300 hover:border-gray-200 hover:shadow-lg hover:shadow-gray-600/5 dark:border-gray-700 dark:bg-gray-800 dark:hover:border-gray-600',
		className,
	]}
>
	<div class="relative overflow-hidden">
		<Picture
			src={news.data.imageLight}
			alt={news.data.title}
			widths={SITE.imageWidths}
			formats={SITE.imageFormats}
			class="aspect-video w-full object-cover object-top transition duration-500 group-hover:scale-105 dark:hidden"
		/>
		<Picture
			src={news.data.imageDark}
			alt={news.data.title}
			widths={SITE.imageWidths}
			formats={SITE.imageFormats}
			class="hidden aspect-video w-full object-cover object-top transition duration-500 group-hover:scale-105 dark:block"
		/>
	</div>
	<div class="flex flex-col p-6">
		<span class="text-sm font-medium text-gray-400 dark:text-gray-500">
			{formatDate(news.data.date)}
		</span>
		<h3 class="mt-2 text-xl font-semibold text-gray-900 dark:text-white">
			{news.data.title}
		</h3>
		<div
			class="mt-4 line-clamp-3 text-sm leading-relaxed text-gray-600 dark:text-gray-300"
		>
			<Content />
		</div>
	</div>
</article>

