---
import { Icon } from 'astro-icon/components'
---

<aside
	id="prototype-switcher"
	aria-label="Prototyp-Variante wechseln"
	class="fixed right-1/2 bottom-6 z-50 hidden translate-x-1/2 rounded-full border border-gray-200 bg-white/95 px-4 py-2 shadow-xl shadow-black/10 backdrop-blur-sm dark:border-gray-700 dark:bg-gray-900/95"
>
	<div class="flex items-center gap-3">
		<a
			id="prototype-prev"
			href="?variant=A"
			class="flex items-center justify-center rounded-full p-2 text-gray-600 transition hover:bg-gray-100 hover:text-gray-900 dark:text-gray-300 dark:hover:bg-gray-800 dark:hover:text-white"
			aria-label="Vorherige Variante"
		>
			<Icon name="mdi:chevron-left" class="size-5" />
		</a>
		<span
			id="prototype-label"
			class="min-w-[9rem] text-center text-sm font-semibold text-gray-900 dark:text-white"
		>
			Variante
		</span>
		<a
			id="prototype-next"
			href="?variant=B"
			class="flex items-center justify-center rounded-full p-2 text-gray-600 transition hover:bg-gray-100 hover:text-gray-900 dark:text-gray-300 dark:hover:bg-gray-800 dark:hover:text-white"
			aria-label="Nächste Variante"
		>
			<Icon name="mdi:chevron-right" class="size-5" />
		</a>
	</div>
</aside>

<script>
	const variants = ['A', 'B', 'C'] as const
	const labels: Record<(typeof variants)[number], string> = {
		A: 'Split-Layout',
		B: 'Magazin-Layout',
		C: 'Bento-Layout',
	}

	const switcher = document.getElementById('prototype-switcher')
	const prev = document.getElementById('prototype-prev') as HTMLAnchorElement | null
	const next = document.getElementById('prototype-next') as HTMLAnchorElement | null
	const label = document.getElementById('prototype-label')

	function getCurrent(): (typeof variants)[number] | null {
		const value = new URLSearchParams(window.location.search).get('variant')
		return variants.includes(value as (typeof variants)[number]) ? (value as (typeof variants)[number]) : null
	}

	function update() {
		const current = getCurrent()
		if (!current || !switcher || !prev || !next || !label) {
			switcher?.classList.add('hidden')
			return
		}

		switcher.classList.remove('hidden')
		const index = variants.indexOf(current)
		const prevKey = variants[(index + variants.length - 1) % variants.length]
		const nextKey = variants[(index + 1) % variants.length]
		prev.href = `?variant=${prevKey}`
		next.href = `?variant=${nextKey}`
		label.textContent = `Variante ${current} — ${labels[current]}`
	}

	function navigate(href: string) {
		if (!href) return
		history.replaceState(null, '', href)
		window.dispatchEvent(new CustomEvent('prototype:variant-change'))
		update()
	}

	prev?.addEventListener('click', (event) => {
		event.preventDefault()
		navigate(prev.href)
	})

	next?.addEventListener('click', (event) => {
		event.preventDefault()
		navigate(next.href)
	})

	document.addEventListener('keydown', (event) => {
		const target = event.target as HTMLElement
		if (
			target.tagName === 'INPUT' ||
			target.tagName === 'TEXTAREA' ||
			target.isContentEditable
		) {
			return
		}

		if (event.key === 'ArrowLeft') {
			event.preventDefault()
			prev?.click()
		} else if (event.key === 'ArrowRight') {
			event.preventDefault()
			next?.click()
		}
	})

	window.addEventListener('popstate', update)
	update()
</script>
